-- Data of CCDDocumentDaoTest (H2, Oracle mode): a standardized CCD with its raw row and association, the raw child
-- tables of the document viewer, the UPHN payload rows.

CREATE ALIAS FN_TO_DATE FOR "gov.ny.state.doh.bhae.nyehms.web.spring.dao.document.CCDDocumentDaoTest.fnToDate";

CREATE TABLE STD_CCD_DOC (DOCUMENT_ID NUMBER, FNAME VARCHAR2(100), MNAME VARCHAR2(100), LNAME VARCHAR2(100), SUFFIX VARCHAR2(20), DOB_TEXT VARCHAR2(20),
    GENDER VARCHAR2(10), ETHNICITY VARCHAR2(50), RACE_WHITE VARCHAR2(5), RACE_BLACK VARCHAR2(5), RACE_ASIAN VARCHAR2(5), RACE_INDIAN VARCHAR2(5),
    RACE_PACIFIC VARCHAR2(5), RACE_UNKNOWN VARCHAR2(5), RACE_OTHER VARCHAR2(5), RACE_OTHER_TEXT VARCHAR2(100), LANGUAGE VARCHAR2(50),
    PERSON_ADDRESS VARCHAR2(200), PERSON_CITY VARCHAR2(100), PERSON_STATE VARCHAR2(10), PERSON_ZIP VARCHAR2(10), PERSON_PLUS4 VARCHAR2(4),
    PERSON_COUNTY VARCHAR2(50), PERSON_PHONE VARCHAR2(20), PERSON_ADDRESS_ID NUMBER, PERSON_COUNTRY VARCHAR2(50), PERSON_PHONE_HOME VARCHAR2(20),
    PERSON_PHONE_CELL VARCHAR2(20), PERSON_PHONE_WORK VARCHAR2(20), ADDRESS_USE VARCHAR2(10), USEABLE_PERIOD_LOW VARCHAR2(20), USEABLE_PERIOD_HIGH VARCHAR2(20),
    PERSON_LATITUDE VARCHAR2(20), PERSON_LONGITUDE VARCHAR2(20), PERSON_CENSUS_TRACT VARCHAR2(20), CREATE_DATE DATE, MPI VARCHAR2(50), MATCH_CD VARCHAR2(5),
    CURRENT_PROCESS_STATUS NUMBER, MATCH_PASS VARCHAR2(5), MATCH_WEIGHT NUMBER, MATCHED_STATENO VARCHAR2(20), QS_PARENT_DOC_ID NUMBER, MATCHED_PROCESS_DATE DATE,
    UPHN_TRANX_IN_ID NUMBER, HIE_NAME VARCHAR2(50), RACE_UNTRANSLATABLE VARCHAR2(100), EHARS_IMPORT_DATE DATE, EHARS_STATUS_CD VARCHAR2(5), FLUX_MATCH_CD VARCHAR2(5));
INSERT INTO STD_CCD_DOC (DOCUMENT_ID, FNAME, MNAME, LNAME, DOB_TEXT, GENDER, ETHNICITY, RACE_WHITE, LANGUAGE, PERSON_ADDRESS, PERSON_CITY, PERSON_STATE, PERSON_ZIP,
    PERSON_PHONE, PERSON_ADDRESS_ID, PERSON_PHONE_HOME, PERSON_PHONE_CELL, ADDRESS_USE, CREATE_DATE, MPI, CURRENT_PROCESS_STATUS, UPHN_TRANX_IN_ID,
    EHARS_IMPORT_DATE, EHARS_STATUS_CD)
    VALUES (100, 'JOHN', 'Q', 'DOE', '01/02/1980', 'M', 'NOT HISPANIC', 'Y', 'ENGLISH', '1 MAIN ST', 'ALBANY', 'NY', '12201',
    '5551111', 77, '5552222', '5553333', 'HP', TIMESTAMP '2024-01-02 03:04:05', 'MPI1', 10, 12,
    TIMESTAMP '2024-02-03 00:00:00', 'I');
INSERT INTO STD_CCD_DOC (DOCUMENT_ID, FNAME, LNAME, MPI, CURRENT_PROCESS_STATUS) VALUES (101, 'JANE', 'ROE', 'MPI2', 10);

CREATE TABLE RAW_CCD_DOC (DOCUMENT_ID NUMBER, UPHN_TRANX_IN_ID NUMBER, MPI VARCHAR2(50), FNAME VARCHAR2(100), MNAME VARCHAR2(100), LNAME VARCHAR2(100),
    DOB_TEXT VARCHAR2(20), GENDER VARCHAR2(10), PERSON_PHONE_HOME VARCHAR2(20), PERSON_PHONE_WORK VARCHAR2(20), PERSON_PHONE_CELL VARCHAR2(20),
    RACE_DESC VARCHAR2(100), RACE_CODE VARCHAR2(20), ETHNICITY VARCHAR2(50), LANGUAGE VARCHAR2(50), CURRENT_PROCESS_STATUS NUMBER, HIE_NAME VARCHAR2(50),
    PAYLOADNAME VARCHAR2(200), DATE_CREATED DATE, IS_DUPLICATE VARCHAR2(1), REMOVED VARCHAR2(1), PROCESS_DATE DATE, CLEARTEXT_PAYLOAD CLOB);
INSERT INTO RAW_CCD_DOC (DOCUMENT_ID, UPHN_TRANX_IN_ID, MPI, CURRENT_PROCESS_STATUS) VALUES (100, 12, 'MPI1', 10);

CREATE TABLE PERSON_DOC_ASSOCIATION (PERSON_DOC_ASSOCIATION_ID NUMBER, DOCUMENT_ID NUMBER, STATENO VARCHAR2(20), ASSOCIATION_STATUS_CODE VARCHAR2(10),
    WORKER_ID NUMBER, ASSOCIATION_DATE DATE, DISCARD_STATUS VARCHAR2(5), DISSASSOCIATION_DATE DATE, SURV_ASSESS_STATUS NUMBER, PS_ASSESS_STATUS NUMBER, SURV_ASSIGNMENT_ID NUMBER);
